-- ============================================================
-- SEED EXT 4: Módulo 04 — Present Continuous (ex 145-220)
-- Novos tópicos: PC em gêneros textuais, PC em academic writing,
-- PC para tendências graduais, PC integrado TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'present-continuous';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo present-continuous não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 41: PC para tendências graduais (academic writing)
  (cid,41,145,'gap_fill','Global temperatures _____ (rise) at an accelerating rate, according to data from the past fifty years.','are rising',NULL,'PC for ongoing, progressive trend in academic writing.','easy'),
  (cid,41,146,'gap_fill','The proportion of renewable energy in the global mix _____ (grow) steadily, though fossil fuels still dominate.','is growing',NULL,'PC for gradual but ongoing change.','easy'),
  (cid,41,147,'multiple_choice','Why is present continuous preferred over present simple in "Younger generations are increasingly questioning traditional career paths"?','Because the change is gradual and ongoing, not a fixed, universal fact.','["Present simple is incorrect here","Because younger generations are present in the room","Because the change is gradual and ongoing, not a fixed, universal fact.","Because ''increasingly'' requires the continuous"]','PC = ongoing, evolving trend. PS = stable, established fact.','medium'),
  (cid,41,148,'gap_fill','The gap between urban and rural incomes _____ (widen) in most emerging economies, posing significant policy challenges.','is widening',NULL,'PC for gradual economic trend.','easy'),
  (cid,41,149,'gap_fill','New forms of resistance _____ (emerge) as traditional protest movements _____ (adapt) to digital environments.','are emerging / are adapting',NULL,'Two simultaneous ongoing changes: PC + PC.','easy'),
  (cid,41,150,'multiple_choice','Which sentence uses present continuous for a TEMPORARY situation (not a trend)?','He is currently teaching at the university while his book is being published.','["He teaches at the university (present simple — permanent).","He is currently teaching at the university while his book is being published.","He taught at the university last year (past — completed).","He will be teaching at the university (future continuous)."]','PC = temporary arrangement (currently, while).','medium'),

  -- BLOCK 42: PC vs PS em duplos contextos
  (cid,42,151,'multiple_choice','What is the difference: "She works at the lab" vs "She is working at the lab"?','"Works" = her permanent job. "Is working" = her current temporary activity.','["They are identical","''Works'' = her permanent job. ''Is working'' = her current temporary activity.","Works is more formal","Is working is always wrong for jobs"]','"Work" = habitual/permanent (PS). "Is working" = now/temporarily (PC).','medium'),
  (cid,42,152,'gap_fill','The economy _____ (usually/grow) at around 2% per year, but this year it _____ (contract) sharply.','usually grows / is contracting',NULL,'PS for normal pattern + PC for current exception.','medium'),
  (cid,42,153,'gap_fill','Researchers _____ (typically/conduct) experiments in controlled environments, but this team _____ (collect) field data in remote ecosystems.','typically conduct / is collecting',NULL,'PS for general practice + PC for current specific project.','medium'),
  (cid,42,154,'multiple_choice','Which sentence correctly uses BOTH present simple and present continuous?','Scientists generally study volcanoes from a safe distance, but this team is currently operating sensors inside an active caldera.','["Scientists are generally studying volcanoes, but this team currently studies sensors inside a caldera.","Scientists generally study volcanoes from a safe distance, but this team is currently operating sensors inside an active caldera.","Scientists study volcanoes, but this team is operating sensors inside a caldera when they return.","Scientists generally are studying volcanoes, but this team operates sensors inside a caldera now."]','PS (general practice) + PC (current exception).','hard'),
  (cid,42,155,'gap_fill','Most universities _____ (require) standardized test scores, but some institutions _____ (now/move) toward holistic evaluation.','require / are now moving',NULL,'PS for standard practice + PC for emerging change.','medium'),
  (cid,42,156,'gap_fill','The traditional lecture format _____ (remain) dominant, but hybrid models _____ (gain) traction in many institutions.','remains / are gaining',NULL,'PS for current stable state + PC for emerging trend.','medium'),

  -- BLOCK 43: PC passivo — ongoing processes
  (cid,43,157,'gap_fill','New data centers _____ (construct/passive) across Southeast Asia to meet growing demand for cloud computing.','are being constructed',NULL,'"Are being + past participle" = ongoing passive.','medium'),
  (cid,43,158,'gap_fill','The bridge _____ (inspect/passive/currently) after cracks _____ (discover/passive) last week.','is currently being inspected / were discovered',NULL,'PC passive for current inspection + past passive for prior discovery.','hard'),
  (cid,43,159,'multiple_choice','Which sentence uses present continuous passive CORRECTLY?','The new curriculum is being developed by a team of educators and cognitive scientists.','["The new curriculum is developing by educators and scientists.","The new curriculum is being developing by educators and scientists.","The new curriculum is being developed by a team of educators and cognitive scientists.","The new curriculum has been developing by educators and scientists."]','"Is being + past participle" = correct PC passive.','medium'),
  (cid,43,160,'gap_fill','More than 5,000 clinical trials _____ (currently/conduct/passive) worldwide to test potential treatments for Alzheimer''s disease.','are currently being conducted',NULL,'PC passive for large-scale ongoing research activity.','hard'),
  (cid,43,161,'gap_fill','The ecosystem _____ (not/currently/monitor/passive) effectively — funding cuts have left large areas unobserved.','is not currently being monitored',NULL,'Negative PC passive for absence of ongoing activity.','hard'),

  -- BLOCK 44: PC em negação e interrogação formal
  (cid,44,162,'gap_fill','Why _____ (not/the government/take) action on this issue despite clear evidence of the need for reform?','is the government not taking / isn''t the government taking',NULL,'PC question: why + is/are + subject + not + -ing.','medium'),
  (cid,44,163,'multiple_choice','Which question correctly uses present continuous?','Are researchers currently conducting longitudinal studies on this population?','["Do researchers currently conduct longitudinal studies on this population? (PS — wrong for current ongoing activity)","Are researchers currently conducting longitudinal studies on this population?","Have researchers currently conducted longitudinal studies?","Were researchers currently conducting longitudinal studies?"]','PC question: are + subject + -ing for current ongoing activity.','medium'),
  (cid,44,164,'gap_fill','The patient _____ (not/respond) to the standard treatment protocol, which _____ (suggest) a possible resistance mechanism.','is not responding / suggests',NULL,'PC negative for ongoing non-response + PS for implication (stative).','hard'),
  (cid,44,165,'gap_fill','What _____ (prevent) policymakers from implementing the recommendations that scientists _____ (repeatedly/make)?','is preventing / are repeatedly making',NULL,'PC questions with WH word: what + is + -ing.','hard'),

  -- BLOCK 45: TOEFL Reading
  (cid,45,166,'multiple_choice','[TOEFL Reading] "Populations in developing nations are increasingly migrating to urban centers in search of economic opportunity." The present continuous expresses:','An ongoing demographic trend currently happening at a large scale.','["A temporary individual action","An ongoing demographic trend currently happening at a large scale.","A scheduled future event","A historical habit"]','PC for large-scale ongoing trend in academic/journalistic writing.','easy'),
  (cid,45,167,'gap_fill','[TOEFL Reading] "Arctic sea ice _____ (melt) at a rate that exceeds climate model predictions from just a decade ago." Best form?','is melting',NULL,'PC for ongoing alarming environmental process.','easy'),
  (cid,45,168,'multiple_choice','[TOEFL Reading] "The research team is currently analyzing the genomes of 1,200 participants." This PC construction emphasizes:','The analysis is in progress now — it is not yet complete.','["The team will analyze in the future","The team always analyzes genomes","The analysis is in progress now — it is not yet complete.","The team analyzed in the past"]','PC = currently ongoing, incomplete action.','easy'),
  (cid,45,169,'gap_fill','[TOEFL Reading] "New evidence _____ (emerge) that challenges the consensus view, though the scientific community _____ (not/yet/fully/accept) its implications." Best forms?','is emerging / has not yet fully accepted',NULL,'PC for emerging evidence + PP for incomplete acceptance.','hard'),
  (cid,45,170,'multiple_choice','[TOEFL Reading] In "The company is losing market share to competitors that are innovating more rapidly," what does the PC "is losing" indicate?','An ongoing process, not yet complete, that began in the past and is still happening.','["A habitual company practice","A future prediction","An ongoing process, not yet complete, that began in the past and is still happening.","A past completed event"]','PC = ongoing, in-progress trend in business/economic context.','easy'),

  -- BLOCK 46: TOEFL Speaking
  (cid,46,171,'production','[TOEFL Speaking — 45s] A reading describes how digital technology is transforming higher education. Discuss current changes using PC (active and passive), and contrast with PS for established practices.','',NULL,'Higher education is undergoing profound transformation driven by digital technology. Universities are increasingly offering hybrid and fully online programs that serve students who cannot attend traditional campuses. Simultaneously, AI tools are being integrated into assessment design, and personalized learning platforms are being developed that adapt to individual student progress. Traditional lectures remain the dominant mode of instruction in many institutions, but the proportion of active learning formats — problem-based learning, flipped classrooms, peer instruction — is growing steadily. The pandemic accelerated many of these trends by forcing rapid adoption of digital tools that had previously been introduced only cautiously. At the same time, employers are increasingly valuing micro-credentials and competency-based qualifications alongside or instead of traditional degrees.','hard'),
  (cid,46,172,'production','[TOEFL Speaking — 45s] Describe what is currently happening in your field of study or a topic you know well. Use PC for ongoing developments, PS for established knowledge, and PC passive for processes.','',NULL,'Environmental science is currently grappling with the challenge of communicating the urgency of climate change while maintaining scientific precision. New monitoring technologies — including satellite-based sensors and deep-sea buoys — are being deployed to provide real-time data on atmospheric and oceanic conditions. Researchers are increasingly collaborating across disciplines, combining physical climate modeling with economics, public health, and political science to develop more comprehensive assessments of climate risk. Meanwhile, the public is being bombarded with conflicting information, and trust in scientific institutions remains fragile in many countries. The field knows that the physical science is settled — temperatures are rising, ice is melting, sea levels are increasing — but the socioeconomic consequences are still being studied and the policy solutions remain deeply contested.','hard'),

  -- BLOCK 47: TOEFL Writing
  (cid,47,173,'production','[TOEFL Writing — 150 words] Write an academic paragraph on urbanization trends using PC for ongoing changes, PS for established patterns, PC passive for processes currently underway.','',NULL,'Urbanization is accelerating across much of the developing world, with hundreds of millions of people relocating from rural to urban areas in search of economic opportunity. This movement is transforming landscapes, labor markets, and social structures at a pace that urban planners and public services frequently struggle to match. In sub-Saharan Africa and South Asia, informal settlements are expanding rapidly on the peripheries of major cities, as rural migrants who cannot afford formal housing seek any available shelter. Infrastructure — water systems, sanitation networks, transportation grids — is being extended to accommodate growing populations, but the pace of construction consistently lags behind demand. At the same time, new forms of urban agriculture are emerging within cities, and digital technology is being used to improve the coordination of public services. Urban populations are increasingly diverse, placing new demands on educational systems and healthcare networks.','hard'),
  (cid,47,174,'production','[TOEFL Writing — Error Correction] Fix PC errors: "The economy grows steadily this year (should be ongoing trend). Scientists are currently studying the effects of X (correct — no fix). She is knowing the answer already. The infrastructure is being building. More universities are move toward online learning."','',NULL,'grows → is growing (PC for ongoing current trend — this year implies current temporary situation); scientists are currently studying = correct; is knowing → knows (stative verb: know → no PC); is being building → is being built (passive PC: is being + past participle, not -ing); are move → are moving (PC = are + -ing form).','hard'),

  -- BLOCK 48: Mixed consolidation
  (cid,48,175,'production','[TOEFL Writing — 200 words] Write a body paragraph on the future of work. Use: PC for current trends (×4), PC passive (×2), PS for established facts (×2), stative verbs correctly (×2).','',NULL,'The nature of work is changing fundamentally, driven by automation, digitization, and the rise of platform-based employment models. Artificial intelligence is replacing routine cognitive tasks that were previously the exclusive domain of knowledge workers, while robotics is automating many manufacturing and logistics processes. At the same time, entirely new categories of work are emerging: data scientists, AI trainers, and digital content creators represent occupations that barely existed a decade ago. Research consistently shows that the workers most vulnerable to displacement are those in middle-skill roles — administrative, clerical, and semi-skilled manufacturing positions — rather than either high-skill or low-skill jobs, a pattern that economists describe as labor market polarization. This appears to be a structural feature of technology-driven economic change rather than a temporary disruption. In this context, educational systems are being redesigned to emphasize adaptability, critical thinking, and lifelong learning, rather than the acquisition of fixed technical skills that may become obsolete within years of graduation. Governments are developing new social insurance mechanisms to support workers displaced by automation, though the political challenges of financing such programs seem significant.','hard'),
  (cid,48,176,'production','[TOEFL Writing — 200 words] Write a body paragraph on biodiversity and extinction using PC, PS, PC passive, and stative verbs.','',NULL,'Biodiversity is declining at a rate that the scientific community now recognizes as a mass extinction event — only the sixth in the history of multicellular life on Earth. Species are disappearing at an estimated one hundred to one thousand times the natural background rate, driven primarily by habitat destruction, pollution, invasive species, overexploitation, and climate change. Tropical forests contain the majority of terrestrial biodiversity, and they are being cleared at a rate of approximately fifteen billion trees per year globally. Marine ecosystems face similar pressures: coral reefs are bleaching and dying as ocean temperatures rise, and fish populations are collapsing in regions where overfishing is proceeding faster than reproduction allows. Scientists know that biodiversity loss reduces ecosystem resilience — the capacity of natural systems to absorb disturbance and recover — meaning that the more species disappear, the more vulnerable remaining ecosystems become to further degradation. The services these ecosystems provide to humanity — clean water, flood mitigation, soil fertility, carbon sequestration, pollination — are worth trillions of dollars annually and remain irreplaceable. New protected areas are being established in many countries, but their coverage remains insufficient to halt the trajectory of global biodiversity loss.','hard'),
  (cid,48,177,'production','[TOEFL Writing — integrated 200 words] Discuss how cities are adapting to climate change. Use PC, PC passive, PS, and PC contrasted with PS.','',NULL,'Cities around the world are developing and implementing adaptation strategies in response to the escalating impacts of climate change. Coastal cities such as Rotterdam, New York, and Tokyo are investing billions in flood barriers, elevated infrastructure, and managed retreat from vulnerable zones. In many tropical cities, cooling centers and urban tree canopies are being established to protect residents from extreme heat events that are becoming more frequent and severe. Meanwhile, water management systems are being redesigned across arid urban regions to capture and recycle scarce rainfall more efficiently. Not all cities are adapting at the same pace: resource-rich cities in wealthy countries are generally leading the transition, while cities in low-income countries — which often face the greatest climate risks — lack the financial and technical capacity to implement comprehensive adaptation measures. Urban planning traditionally focuses on growth and economic development, but cities are now beginning to integrate climate risk assessment into all major infrastructure decisions. The challenge is immense: the world is urbanizing rapidly at the same time that climate impacts are intensifying, meaning that the decisions made in the next decade about how cities are built and managed will shape human vulnerability to climate change for generations to come.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
